/// Fetches the next lexer token, or errors if none is found.
fn next(&mut self) -> Result<Token> {
    match self.lexer.next() {
        Some(Ok(t)) => Ok(t),
        Some(Err(e)) => Err(e),
        None => Err(errinput!("unexpected end of input")),
    }
}
